\begin{equation}\label{eq:primal}
\mathrm{(P):} \ \ \ \ \ \ \ \min_\beta P(\beta):=\tfrac{1}{n }\sum_{j=1}^{n}l_{j}(x_j^T\beta)+R(\beta) \ ,
\end{equation}

where $\beta \in \RR^p$, $l_j(\cdot) : \RR \rightarrow \RR$, $j=1, \ldots, n$, is a univariate function (the $j^{\mathrm{th}}$ loss function), $s_j = x_j^T\beta$ is the ``predicted value'' of the model $\beta$ for the data sample $x_j$, and $R(\cdot)$ is some other function that can be used to model a variety of properties such as a regularizer, an indicator function of a feasible region $Q$, a penalty term, coupling constraints, etc.  Notice that the predicted value $s_j= x_j^T\beta$ is a linear function of $\beta$.  Hence in the intentional context of empirical loss minimization we refer to \eqref{eq:primal} as (empirical) loss minimization with ``linear prediction.''  This structure arises quite generally throughout statistical and machine learning, which we illustrate below via several salient examples.  Throughout this paper we assume the following regarding the functions in our problem setup \eqref{eq:primal}:\medskip


\begin{ass}\label{ass:smooth}  The following hold:
\begin{enumerate}
\item for $j=1, \ldots, n$, the univariate function $l_j(\cdot)$ is $\gamma$-smooth, namely $| \dot l_j(a) - \dot l_j(b)| \le \gamma |a-b|$ for all $a$, $b$, and is strictly convex,
\item $\dom R(\cdot)$ is bounded, and the subproblem
\begin{equation}\label{eq:sub}
\min_\beta c^T\beta +R(\beta)
\end{equation}
attains its optimum and can be easily solved for any $c$, and
\item $ 0 \in \dom R(\cdot)$.
\end{enumerate}
\end{ass}

Let $X \in \RR^{n \times p}$ denote the data matrix whose rows are comprised of the vectors $x_1, \ldots, x_n$, i.e., the $j^{\mathrm{th}}$ row of $X$ is the vector $x_j$, $j=1, \ldots, n$.  Let us define $L(s): \RR^n \rightarrow \RR$ by $L(s) :=\sum_{j=1}^n l_j(s_j)$ which is the total losses associated with $s \in \RR^n$.  We refer to $s=X\beta$ as the ``predicted values'' in the context of empirical loss minimization.


\begin{algorithm}
\caption{Stochastic Generalized Frank-Wolfe with Stochastic Substitute Gradient}\label{al:SFW}
$ \ $
\begin{algorithmic}
\STATE {\bf Initialize.}  Initialize with $\bbeta^{-1}=0$, $s^0=0$, and substitute gradient $d^0=\frac{1}{n}X^T\nabla L(s^0)$, with
step-size sequences $\{\alpha_{i}\} \in (0,1]$ and $\{\eta_{i}\} \in (0,1]$.  \medskip

\STATE  For iterations $i=0,1, \ldots $

\ \ \ \ \ \ \  {\bf Solve l.o.o. subproblem:} Compute $\tbeta^{i} \in \arg\min_{\beta}\left\{\left( d^i\right)^{T}\beta+R(\beta)\right\}$

\ \ \ \ \ \ \  {\bf Choose random index:}  Choose $j_{i} \in {\cal U}[1, \ldots, n]$

\ \ \ \ \ \ \  {\bf Update $s$ value:} $s_{j_i}^{i+1}\leftarrow(1-\eta_{i})s_{j_i}^{i}+\eta_{i}(x_{j_{i}}^{T}\tbeta^{i})$,  and $s_{j}^{i+1} \gets s_{j}^{i}$ for $j \ne j_i$ \medskip

\ \ \ \ \ \ \  {\bf Update substitute gradient:}  $d^{i+1}= \frac{1}{n}X^T\nabla L(s^{i+1}) =  d^i+\frac{1}{n}\left(\dot{l}_{j_{i}}(s^{i+1}_{j_i})-\dot{l}_{j_{i}}(s^i_{j_{i}})\right)x_{j_{i}}$\\ \medskip

\ \ \ \ \ \ \  {\bf Update primal variable:} $\bbeta^{i} \leftarrow (1-\alpha_i) \bbeta^{i-1} + \alpha_i \tbeta^i$.\medskip

\ \ \ \ \ \ \  {\bf (Optional Accounting:)} $w^{i+1} \gets \nabla L(s^{i+1})$ \medskip
\end{algorithmic}
\end{algorithm}

\subsection{Notation} We use $e_j$ to denote the $j^{\mathrm{th}}$ unit coordinate vector in $\RR^p$.  The $\ell_p$ norm is denoted $\|\cdot\|_p$.  We use $\dl_j(\cdot)$ to denote the first derivative of $l_j(\cdot)$.  The Bregman distance function associated with a convex function $h(\cdot)$ is defined as $\Dh(y,x):= h(y) - h(x) - \nabla h(x)^T(y-x)$.  We use $\EE$ to denote expectation and $\EE_{j_i}$ to denote expectation conditional on the randomly chosen index $j_i$.  For indicator functions, we use $\bI_Q(\cdot)$ to denote the indicator function for the set $Q$, namely $\bI_Q(\beta):=0$ if $\beta \in Q$, and $\bI_Q(\beta) :=+\infty$ otherwise; and we use $\bI_{\{\mathrm constraint\}}(\beta)$ to denote the indicator function of a particular constraint (or condition), namely $\bI_{\{\mathrm constraint\}}(\beta):=0$ if the constraint is true at $\beta$, and $\bI_{\{\mathrm constraint\}}(\beta) :=+\infty$ otherwise.  In a slight abuse of terminology we refer to the ``subgradient'' of a concave function when it is perhaps more technically accurate to refer to this as a sup-gradient.   A differentiable function $\ff$ is $\mu$-strongly convex with respect to a norm $\|\cdot\|$ if it holds that $f(y) \ge f(x) + \nabla f(x)^T(y-x) + \tfrac{\mu}{2}\|y-x\|^2$ for all $x,y \in \dom f(\cdot)$.  A differentiable function $\ff$ is $\mu$-strongly convex with respect to a reference function $h(\cdot)$ if it holds that $f(y) \ge f(x) + \nabla f(x)^T(y-x) + \mu \Dh(y,x)$ for all $x,y \in \dom f(\cdot)$.


$$
f^*(y) := \sup_{x\in \dom f(\cdot)} \{y^T x - f(x)\} \ .
$$
We will also be interested in the following dual problem of \eqref{eq:primal} that is constructed using the conjugate functions of the component functions of  \eqref{eq:primal}:
\begin{equation}\label{eq:dual}
\mathrm{(D):} \ \ \ \ \ \ \ \max_{w} D(w):=-R^{*}\left(-\tfrac{1}{n}X^{T}w\right)-\tfrac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w_{j}) \ .
\end{equation}
Notice that we can write:
\begin{equation}\label{eq:altered}R^{*}\left(-\tfrac{1}{n}X^{T}w\right)= - \min_{\beta}\left\{\tfrac{1}{n} w^{T}X\beta+R(\beta)\right\}  \ .
\end{equation}
Also, defining the convex/concave saddle-function $\phi(\cdot,\cdot)$:
\begin{equation}\label{eq:primal-dual}
\phi(\beta,w):=\tfrac{1}{n} w^{T}X\beta-\tfrac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})+R(\beta) \ ,
\end{equation} we can write (P) and (D) in saddlepoint minimax format as:

\begin{equation}\label{eq:minmax} \mathrm{(P):} \ \ \min_{\beta} \max_{w} \phi(\beta,w) \ \ \ \ \  \ \ \mathrm{and} \ \ \ \ \ \ \ \  \mathrm{(D):} \ \ \max_{w}\min_{\beta} \phi(\beta,w) \ .
\end{equation}


\begin{algorithm}
\caption{Randomized Coordinate Mirror Descent applied to the dual problem \eqref{eq:dual}}\label{al:RCMD}
$ \ $
\begin{algorithmic}
\STATE {\bf Initialize.}  Define the prox function $h(w):=\frac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})$.  Initialize with $w^{0}=\arg\min_{w} \tfrac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})$ and
step-size sequences $\{\alpha_{i}\} \in (0,1]$ and $\{\eta_{i}\} \in (0,1]$. (Optional: set $\bbeta^{-1}=0$.)\medskip

\STATE  For iterations $i=0,1, \ldots $

\ \ \ \ \ \ \  {\bf Compute Randomized Coordinate of Subgradient of $D(\cdot)$ at $w^i$}\\

\ \ \ \ \ \ \ \ \ \ \ \ Compute $\tbeta^{i} \in \arg\min_{\beta}\left\{\left( \tfrac{1}{n}(w^i)^T X \beta+R(\beta) \right) \right\}$ \\ \medskip

\ \ \ \ \ \ \ \ \ \ \ \    {\bf Choose random index.}  Choose $j_{i} \in {\cal U}[1, \ldots, n]$ \\
%Compute $\bar{\beta}^{i}:=\frac{2}{(4n+k)(k+1)}\sum_{i=0}^{i}(2n+k)\tilde{\beta}^{i}=\frac{(4n+k-1)k}{(4n+k)(k+1)}\bar{\beta}^{k-1}+\frac{2(2n+k)}{(4n+k)(k+1)}\tbeta^{i}$
\ \ \ \ \ \ \ \ \ \ \ \  {\bf Compute subgradient coordinate vector:} $\tilde{g}^i \gets \frac{1}{n}\left(x_{j_{i}}^{T}\tbeta^{i}-\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})\right)e_{j_{i}}$ \\ \medskip

\ \ \ \ \ \ \    {\bf Update dual variable:} Compute $w^{i+1}=\arg\min_w \left\{ \left\langle -\eta_{i}\tilde g^i,w-w^{i}\right\rangle +D_{h}(w,w^{i})\right\} $ \\ \medskip

\ \ \ \ \ \ \  {\bf (Optional Accounting:)} $\bbeta^{i} \leftarrow (1-\alpha_i) \bbeta^{i-1} + \alpha_i \tbeta^i$. \medskip

\end{algorithmic}
\end{algorithm}

Let $M := \max_{\beta \in \dom R(\cdot)} \max_{j=1, \ldots, n} \{| x_j^T\beta | \}$, and note that $M < +\infty$ since $\dom R(\cdot)$ is bounded by Assumption \ref{ass:smooth}.\medskip

Let ${\cal W} \subset \RR^n$ be the set of ``optimal $w$ responses'' to values $\beta \in \dom R(\cdot)$ in the saddle-function $\phi(\beta, w)$, namely: $${\cal W} := \{ \hw \in \RR^n : \hw \in \arg \max_w \phi(\hbeta, w) \ \mbox{for~some~} \hbeta \in \dom R(\cdot) \} \ , $$

and let $D_{\max}$ be any upper bound on $D_h (\hw,w^0)$ as $\hw$ ranges over all values in ${\cal W}$, so that
$$
D_h (\hw ,w^0)\le D_{\max} \ \  \mbox{for~all~}  \hw \in \cal W \ .
$$
Note at the moment that there is no guarantee that $D_{\max} < +\infty$, but this will be remedied below in Proposition \ref{prop:Dmax}.\medskip


Notice in Algorithm \ref{al:SFW} and Algorithm \ref{al:RCMD} that $j_i$ is a random variable; and that $s^i$, $d^i$, $w^i$, etc., are random variables that depend on all previous random variable values $j_0, j_1, \ldots, j_{i-1}$, and we denote this string of random variables by 
\begin{equation}\label{eq:xi}
\xi_i=\{j_0, j_1, \ldots, j_{i-1}\} \ .
\end{equation}


\begin{prop}\label{prop:gradient_conjugate}(see \cite{avriel}, \cite{zalinescu}, \cite{kakade2012regularization})
If $f(\cdot)$ is a closed convex function, then ${f}^{**}(\cdot) = f(\cdot)$.  Furthermore:
\begin{enumerate}
\item $\ff$ is $\gamma$-smooth with domain $\RR^p$ with respect to the norm $\|\cdot\|$ if and only if  $f^*(\cdot)$ is $1/\gamma$-strongly convex with respect to the (dual) norm $\|\cdot\|^*$ .
\item If $\ff$ is differentiable and strictly convex, then the following three conditions are equivalent:
\begin{enumerate}
\item $y = \nabla f(x)$
\item $x = \nabla f^*(y)$, and
\item $x^T y = f(x)+f^*(y)$ .
\end{enumerate}
\end{enumerate}
\end{prop}

\begin{lem}\label{tpp} {\bf (Three-Point Property \cite{tseng})} Let $\phi(x)$ be a convex function, and let $\Dh(\cdot, \cdot)$ be the Bregman distance for $\hh$. For a given vector $z$, let
\begin{equation*}
z^+ := \arg\min_{x\in Q} \left\{ \phi(x) + \Dh(x,z) \right\} \ .
\end{equation*}
Then
\begin{equation*}
\phi(x) + \Dh(x,z) \ge \phi(z^+) + \Dh(z^+, z) + \Dh(x,z^+)\ \   for\ all \ x\in Q \ . \qed
\end{equation*}
\end{lem}

