\begin{lem}\label{lem:equi} {\bf (Equivalence Lemma)}  Algorithm \ref{al:SFW} and Algorithm \ref{al:RCMD} are equivalent as follows:  the iterate sequence of either algorithm exactly corresponds to an iterate sequences of the other. \qed
\end{lem}

\begin{prop}\label{prop:wupdate} At iteration $i$ of Algorithm \ref{al:RCMD} it holds that:

(1.) $\dlsji(w_{j_{i}}^{i+1})=(1-\eta_{i})\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i}) + \eta_{i}x_{j_{i}}^{T}\tbeta^{i}$, and

(2.) $w_{j_{i}}^{i+1}=\dot{l}_{j_{i}}\left((1-\eta_{i})\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})+ \eta_{i}x_{j_{i}}^{T}\tbeta^{i}\right) $.
\end{prop}

{\bf Proof:}
Because $h(w)$ is a coordinate-wise separable function, we can rewrite the update for $w_{j_{i}}^{i+1}$ as
\begin{equation*}
\begin{array}{ll}
w_{j_{i}}^{i+1} & =\arg\min_{w_{j_{i}}} \left\langle -\frac{\eta_{i}}{n}\left(x_{j_{i}}^{T}\tbeta^{i}-\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})\right),w_{j_{i}}\right\rangle +D_{\frac{1}{n} l_{j_{i}}^{*}}(w_{j_{i}},w_{j_{i}}^{i})\\ \\

& =\arg\min_{w_{j_{i}}}\left\langle -\eta_{i}\left(x_{j_{i}}^{T}\tbeta^{i}-\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})\right),w_{j_{i}}\right\rangle +D_{ l_{j_{i}}^{*}}(w_{j_{i}},w_{j_{i}}^{i})\\ \\

& =\arg\min_{w_{j_{i}}}\left\langle -\eta_{i}x_{j_{i}}^{T}\tbeta^{i}-(1-\eta_{i})\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i}),w_{j_{i}}\right\rangle +l_{j_{i}}^{*}(w_{j_{i}}) \ .  \end{array}
 \end{equation*}

From the first-order optimality condition of the above $1$-dimensional problem we have $\dls_{j_i}(w_{j_i}^{i+1})=\eta_{i}x_{j_{i}}^{T}\tbeta^{i}+(1-\eta_{i})\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})$, which shows {\it (1.)}; and {\it (2.)} follows directly from {\it (1.)} by the properties of the conjugate function in Proposition \ref{prop:gradient_conjugate}. \qed


{\bf Proof of Lemma \ref{lem:equi}}  We show that the iterate sequence of Algorithm \ref{al:RCMD} corresponds exactly to an iterate sequence of Algorithm \ref{al:SFW}.  The $\{s^i\}$ sequence is not formally defined in Algorithm \ref{al:RCMD}, so let us define $s^i := \nabla L^*(w^i)$ for all $i = 0, 1, \ldots$, which is consistent through conjugacy with the relationship $w^i = \nabla L(s^i)$ in the Optional Accounting step of Algorithm \ref{al:SFW} (see Proposition \ref{prop:gradient_conjugate}).  In order to show the correspondence we proceed by induction on the iteration counter $i$.  For $i=0$ we have from conjugacy that $s^0 := \nabla L^*(w^0) = 0 $ from the definition $w^0$ in the  initialization of Algorithm \ref{al:RCMD}.  We also need to show that $\tbeta^0$ is a solution to the linear optimization oracle problem in Algorithm \ref{al:SFW}.  We have for all $i=0, \ldots$, that:
$$\begin{array}{rcl}
\tbeta^{i} \in \arg\min_\beta\left\{ \tfrac{1}{n}\left(w^{i}\right)^{T}X\beta+R(\beta)\right\}    &=& \arg\min_\beta\left\{ \tfrac{1}{n}\left(\nabla L(s^{i})\right)^{T}X\beta+R(\beta)\right\} \\ \\
&=& \arg\min_\beta\left\{ \left(d^{i}\right)^{T}\beta+R(\beta)\right\} \ ,
\end{array}$$thus showing that $\beta^{i}$ corresponds to a linear optimization oracle solution at iteration $i$ in Algorithm \ref{al:SFW} for all $i=0, \ldots$.  Now suppose that the correspondence holds for some iteration counter $i$, and let us examine $s^{i+1}:= \nabla L^*(w^{i+1})$.  We have from Proposition \ref{prop:wupdate} that:
\begin{equation}\label{robo3}
w_{j_{i}}^{i+1} =\dot{l}_{j_{i}}\left((1-\eta_{i})\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i}) + \eta_{i}x_{j_{i}}^{T}\tbeta^{i} \right)=\dot{l}_{j_{i}}\left((1-\eta_{i})s_{j_{i}}^{i} + \eta_{i}x_{j_{i}}^{T}\tbeta^{i} \right) \ ,
\end{equation}
where the first equality is from Proposition \ref{prop:wupdate} and the second equality uses induction.  This then implies that $$ (1-\eta_{i})s_{j_{i}}^{i} + \eta_{i}x_{j_{i}}^{T}\tbeta^{i} = \dl (w_{j_{i}}^{i+1}) = s^{i+1} \ . $$
And for all coefficient indices $j \ne i $ we have
$$s_j^{i+1} = \dl^*(w^{i+1}_j) = \dl(w^i_j)= s^i \ , $$
where the second equality follows from conjugacy, whereby $s^{i+1}$ satisfies the update rule as stated in Algorithm \ref{al:SFW}, thus demonstrating that the iterate sequence of Algorithm \ref{al:RCMD} corresponds exactly to an iterate sequence of Algorithm \ref{al:SFW}.  The same type of analysis as above can be used to prove that the iterate sequence of Algorithm \ref{al:SFW} corresponds exactly to an iterate sequence of Algorithm \ref{al:RCMD}. \qed


\begin{prop}\label{prop:Dmax}
	Under Assumption \ref{ass:smooth} it holds that $D_{\max} \le \gamma M^2$.
\end{prop}

\begin{prop}\label{prop:well-behavior-of-w}
	Let $T:=\left\{ w \in \RR^n : |\|w-w^{0}\|_{\infty}\le \gamma M\right\}$.  Then:
	\begin{enumerate}
		\item for any $\hbeta\in \dom R(\cdot)$ it holds that $\argmax_w \phi (\hbeta, w) \in T$, and
		\item for all $w^i$ generated in Algorithm \ref{al:RCMD}, it holds that  $w^i \in T$.
	\end{enumerate}
\end{prop}

\textbf{Proof.} We first prove {\it (1.)}.  Notice that $w_{0}= \nabla L(0)$ and $\argmax_w \phi (\hbeta, w) = \nabla L(X\hbeta)$ (from conjugacy via Proposition \ref{prop:gradient_conjugate}) , whereby the $\gamma$-smoothness of $l_{j}(\cdot)$ implies that
$$
\left\|\arg\max_{w}\phi(\hat{\beta},w)-w_{0}\right\|_{\infty}=\left\| \nabla L(X\hbeta)-\nabla L(0)\right\|_{\infty}=\max_j \left|\dl_j(x_j^T\hat \beta)-\dl_j(0)\right|\le\gamma\max_{j}|x_{j}^{T}\hat \beta| \le \gamma M \ ,
$$


which proves {\it (1.)}. It follows from Proposition \ref{cor:bound} that for any coordinate $j$ and iterate $i$ it holds that $\left|\dot{l}_{j}^{*}(w_{j}^{i})\right|\le M$. Together with $\dls_j(w_j^0)=0$, we have

$$
\tfrac{1}{\gamma}\left|w_{j}^{i}-w_{j}^{0}\right|\le \left|\dot{l}_{j}^{*}(w_{j}^{i})-\dot{l}_{j}^{*}(w_{j}^{0}) \right|\le M \ ,
$$
(where the first inequality is from the $\frac{1}{\gamma}$-strong convexity of $l_j^*(w_j)$), from which it follows that $\|w^i - w^0\|_\infty \le \gamma M$, which proves {\it (2.)}. \qed


{\bf Proof of Proposition \ref{prop:Dmax}:}  Let $L(s):=\sum_{j=1}^n l_j(s_j)$ and $L^*(w):=\sum_{j=1}^n l^*_j(w_j)$, and note that $L(\cdot)$ and $L^*(\cdot)$ are a conjugate pair.  Let $\hw \in \cal W$ and let $\hbeta$ be such that $\hw \in \arg\max_w \phi(\hbeta, w)$.  Then

%It follows Proposition \ref{prop:well-behavior-of-w}.1 that $\hw^k\in T$, therefore for any $k$ we have

\begin{equation*}
\begin{array}{lcl}
D_{h}(\hw, w^0) & = &\tfrac{1}{n}\left( L^*(\hw)-L^*(w^0)\right)\\ \\
& =&\tfrac{1}{n}\left( \left(\hw \right)^{T}X\hbeta-L(X\hbeta) -L^{*}(w^{0})\right)\\ \\
& \le&\tfrac{1}{n}\left(\max_{w\in T,\beta\in \dom R(\cdot)}\left\{ w^{T}X\beta-L(X\beta)\right\} -L^{*}(w^{0})\right)\\ \\
& =&\tfrac{1}{n}\left(\max_{w\in T,\beta\in  \dom R(\cdot)}\left\{ (w-w^{0})^{T}X\beta+\left(w^{0}\right)^{T}X\beta-L(X\beta)\right\} -L^{*}(w^{0})\right)\\ \\
& \le&\tfrac{1}{n}\left(\max_{w\in T,\beta\in  \dom R(\cdot)}\left\{ (w-w^{0})^{T}X\beta\right\} +\max_{\beta\in  \dom R(\cdot)}\left\{ \left(w^{0}\right)^{T}X\beta-L(X\beta)\right\} -L^{*}(w^{0})\right)\\ \\
& \le &\tfrac{1}{n}\left(n\max_{w\in T,\beta\in  \dom R(\cdot)}\|w-w^{0}\|_{\infty}\|X\beta\|_{\infty}+L^{*}(w^{0})-L^{*}(w^{0})\right)\\ \\
& \le &\gamma M^{2} \ ,
\end{array}
\end{equation*}

where the second equality follows from Proposition \ref{prop:gradient_conjugate}, the first inequality uses $\hbeta \in  \dom R(\cdot)$ and $\hw \in T$ (from Proposition \ref{prop:well-behavior-of-w}), and the last inequality uses $\max_{\beta\in  \dom R(\cdot)}\|X\beta\|_{\infty}\le M$. \qed \medskip


\begin{prop}
For all iterates $i$ and any $j\in\left\{ 1,\ldots,n\right\} $ it holds that $\left|\dot{l}_{j}^{*}(w_{j}^{i})\right|\le M$.
\end{prop}

{\bf Proof.} We prove this by induction on $i$. The proposition is true for $i=0$ because $\dot{l}_{j}^{*}(w_{j}^{0})=0$ for all $j$ by the definition of $w^0$. Next suppose that $\left|\dot{l}_{j}^{*}(w_{j}^{i})\right|\le M$ for a given iterate $i$ and for all $j=1, \ldots, n$. Then at iteration $i+1$ and any $j\not=j_{i}$ we have  $w_j^{i+1}=w_j^i$, whereby $\left|\dot{l}_{j}^{*}(w_{j}^{i+1})\right|=\left|\dot{l}_{j}^{*}(w_{j}^{i})\right|\le M$.  And it follows from Proposition \ref{prop:wupdate} that
\[
\left|\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i+1})\right|=\left|\left(1-\eta_{i}\right)\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})+\eta_{i}x_{j_{i}}^T\tbeta^{i}\right|\le(1-\eta_{i})M+\eta_{i}M=M \ ,
\]
and therefore for any $j=1, \ldots, n$, we have $\left|\dot{l}_{j}^{*}(w_{j}^{i+1})\right|\le M$, which completes the proof by induction. \qed


\begin{cor}\label{cor:bound}
$\|\tilde{g}^i\|_{2} =\frac{1}{n}\left| x_{j_{i}}^T \tbeta^i - \dlsji(\wiji) \right| \le \frac{2M}{n}$.
\end{cor}

\begin{prop}\label{prop:strong}
$h(\cdot)$ is
$\frac{1}{n\gamma}$-strongly convex with respect to the norm $\|\cdot\|_{2}$.
\end{prop}

{\bf Proof.} Recall that $h(w)=\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w_{j})$. It follows from Assumption \ref{ass:smooth} and Proposition \ref{prop:gradient_conjugate} that $\dls_j(\cdot)$ is $\frac{1}{\gamma}$-strongly convex. Therefore for any $w^1, w^2 \in \dom h(\cdot)$ it holds that:
\begin{equation*}
\begin{array}{lcl}
h(w^1)& = &\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w^1_{j}) \\ \\
& \ge & \frac{1}{n}\sum_{j=1}^{n}\left( l_{j}^{*}(w^2_{j}) + \dls_j(w_j^2)(w_j^1-w_j^2)+\frac{1}{2\gamma}|w^2_j-w^1_j|^2\right) \\ \\
& = & h(w^2) + \langle\nabla h(w^2), w^1-w^2\rangle + \frac{1}{2n\gamma}\|w^2-w^1\|_2^2 \ . \ \qed
\end{array}
\end{equation*}


\begin{prop}\label{prop:equality}
$\phi(\tbeta^{i},w)=D(w^{i})+\left\langle \nabla_{w}\phi(\tbeta^{i},w^{i}),w-w^{i}\right\rangle -D_{h}(w,w^{i}).$
\end{prop}

\textbf{Proof. } The proof follows from straightforward substitution using $\phi(\tbeta^{i},w)=\frac{1}{n} \left(w^{T}X\tbeta^{i}-\sum_{j=1}^n l_{j}^{*}(w_{j})\right) + R(\tbeta^i)$ and noticing from the construction of $\tbeta^i$ that $D(w^i)=\phi(\tbeta^i, w^i)$. \qed\medskip


\begin{prop}\label{robfriday}  Consider the series $\{ \alpha_i \}$ defined by $\alpha_i = \frac{2(2n+i)}{(4n+i)(i+1)}$ for $i \ge 0$ and define the series $\{\bbeta^i\}$ by $\bbeta^{-1} =0$ and $\bbeta^i = (1-\alpha_i)\bbeta^{i-1} + \alpha_i \tbeta^i$ for $i\ge 0$.  Also define $\gamma_i = 2n+i$ for $i \ge 0$.  Then
$$ \bbeta^k = \frac{\sum_{i=0}^k \gamma_i \tilde{\beta}^i}{\sum_{i=0}^k \gamma_i} \ \ \mbox{for~all~} k \ge 0 \ . $$
\end{prop}

\noindent {\bf Proof:} The proof follows easily by induction and using $\sum_{i=0}^k \gamma_i = \frac{(4n+k)(k+1)}{2}$. \qed


{\bf Proof of Theorem \ref{thm:non-strong}.}  Denote $g^i:=\frac{1}{n} \left( X\tbeta^i-\nabla L^*(w^i)\right)$, whereby $g^i$ is a subgradient of $D(w)$ at $w^i$, and $\tg^i$ is an unbiased estimator of $g^i$ up to the scalar $n$, namely $\EE_{j_i} [ \tg^i ]=\frac{1}{n}g^i$.  Therefore we have for any $i$ and any $w \in \cal W$ that:
\begin{equation}\label{eq:nonsmooth-theonehand}
\begin{array}{ll}
\left\langle -g^i,w-w^{i}\right\rangle  & =n \EE_{j_i} \left[\left\langle -\tg^i,w-w^{i}\right\rangle\right] \\ \\
 & \ge n \EE_{j_i} \left[\left\langle -\tg^i,w^{i+1}-w^{i}\right\rangle +\frac{1}{\eta_{i}}D_{h}(w^{i+1},w^{i})+\frac{1}{\eta_{i}}D_{h}(w,w^{i+1})-\frac{1}{\eta_{i}}D_{h}(w,w^{i})\right]\\ \\
 & \ge n \EE_{j_i} \left[\left\langle -\tg^i,w^{i+1}-w^{i}\right\rangle +\frac{1}{2n\gamma\eta_{i}}\|w^{i+1}-w^{i}\|_{2}^{2}+\frac{1}{\eta_{i}}D_{h}(w,w^{i+1})-\frac{1}{\eta_{i}}D_{h}(w,w^{i})\right]\\ \\
  & \ge n \EE_{j_i} \left[ -\frac{1}{2}n\gamma \eta_{i} \|\tg^i\|_2^2+\frac{1}{\eta_{i}}D_{h}(w,w^{i+1})-\frac{1}{\eta_{i}}D_{h}(w,w^{i})\right]\\ \\
 & \ge -2\gamma M^{2}\eta_{i}+\frac{n}{\eta_{i}}\EE_{j_i} [D_{h}(w,w^{i+1})]-\frac{n}{\eta_{i}}D_{h}(w,w^{i}) \ ,
\end{array}
\end{equation}
where the first inequality is from the ``three point property'' of Tseng (Lemma \ref{tpp} in the Appendix), the second
inequality is due to the fact that $h(w)$ is $\frac{1}{n\gamma}$-strongly convex with respect to the norm $\|\cdot\|_2$ (Proposition \ref{prop:strong}), and the third inequality is an application of the basic inequality $\langle x, y\rangle \le \tfrac{1}{2}\|x\|_2^2 +  \tfrac{1}{2}\|y\|_2^2$,  and the last inequality uses Corollary \ref{cor:bound}.

On the other hand, we have from Proposition \ref{prop:equality} that
% by substituting $\phi(\tbeta^{i},w)=\frac{1}{n} \left(w^{T}X\tbeta^{i}-\sum l_{i}^{*}(w_{i})\right) + R(\tbeta^i)$  we have
\begin{equation}\label{eq:nonsmooth-theotherhand}
\left\langle -g^i,w-w^{i}\right\rangle   =\left\langle -\nabla_{w}\phi(\tbeta^{i},w^{i}),w-w^{i}\right\rangle  =D(w^{i})-\phi(\tbeta^{i},w)-D_{h}(w,w^{i}) \ .
\end{equation}


Combining \eqref{eq:nonsmooth-theonehand} and \eqref{eq:nonsmooth-theotherhand} and rearranging yields
$$
-(\phi(\tbeta^{i},w)-D(w^{i}))\ge-2\gamma M^{2}\eta_{i}+\tfrac{n}{\eta_{i}}\EE_{j_i}[D_{h}(w,w^{i+1})]-\left(\tfrac{n}{\eta_{i}}-1\right)D_{h}(w,w^{i}).
$$
Substituting $\eta_{i}=\frac{2n}{2n+i+1}$ and multiplying by $2n+i$ results, we arrive at the following inequality after rearranging terms:
$$\begin{array}{l}
(2n+i)(\phi(\tbeta^{i},w)-D(w^{i}))\\
\le  \ \ 4n\gamma  M^{2}\left(\tfrac{2n+i}{2n+i+1}\right)+\tfrac{1}{2}\left((2n+i)(2n+i-1)D_{h}(w,w^{i})-(2n+i)(2n+i+1)\EE_{j_i}[ D_{h}(w,w^{i+1})] \right) \ .
\end{array}$$
Summing the above inequality for $i=0,\ldots,k$ and recalling from Proposition \ref{robfriday} that $\bar{\beta}^{k}:=\frac{2}{(4n+k)(k+1)}\sum_{i=0}^{k}(2n+i)\tbeta^{i}$,
and taking the unconditional expectation over $\xi_k$ (recall the definition of $\xi_k$ in \eqref{eq:xi}), we arrive at:
$$\begin{array}{rcl}
\frac{(4n+k)(k+1)}{2}\EE_{\xi_k}[\phi(\bar{\beta}^{k},w)-D(\bar{w}^{k})] & = & \left(\sum_{i=0}^k 2n+i \right)\EE_{\xi_k}[\phi(\bar{\beta}^{k},w)-D(\bar{w}^{k})] \\ \\
& \le & \EE_{\xi_k}\left[\sum_{i=0}^{k}(2n+i)(\phi(\tbeta^{i},w)-D(w^{i}))\right]\\ \\
& \le & 4(k+1)n\gamma M^{2}+\tfrac{1}{2}(2n)(2n-1)D_{h}(w,w^{0})\\ \\
& \le & 4(k+1)n\gamma M^{2}+n(2n-1)D_{\max} \ ,
\end{array}$$
where the first inequality uses the convexity of $\phi(\beta,w)$
over $\beta$ and the concavity of $D(w)$, the second inequality
follows from the summation and canceling terms in the telescoping series, and the third inequality uses $w \in \cal W$.  Choosing $\hw=\arg\max_{w}\phi(\bar{\beta}^{k},w)$,
we have $P(\bar{\beta}^{k})=\phi(\bar{\beta}^{k},\hw)$, which yields:
\[
\EE_{\xi_k}[P(\bar{\beta}^{k})-D(\bar{w}^{k})]\le\frac{8n\gamma M^{2}}{\left(4n+k\right)}+\frac{2n(2n-1)D_{\max}}{(4n+k)(k+1)} \ ,
\]thus showing the first inequality in the statement of the theorem.
The second inequality in the statement of the theorem then follows as a simple application of Proposition \ref{prop:Dmax}. \qed

