\begin{algorithm}
\caption{Stochastic Generalized Frank-Wolfe with Stochastic Substitute Gradient}\label{al:SFW}
$ \ $
\begin{algorithmic}
\STATE {\bf Initialize.}  Initialize with $\bbeta^{-1}=0$, $s^0=0$, and substitute gradient $d^0=\frac{1}{n}X^T\nabla L(s^0)$, with
step-size sequences $\{\alpha_{i}\} \in (0,1]$ and $\{\eta_{i}\} \in (0,1]$.  \medskip

\STATE  For iterations $i=0,1, \ldots $

\ \ \ \ \ \ \  {\bf Solve l.o.o. subproblem:} Compute $\tbeta^{i} \in \arg\min_{\beta}\left\{\left( d^i\right)^{T}\beta+R(\beta)\right\}$

\ \ \ \ \ \ \  {\bf Choose random index:}  Choose $j_{i} \in {\cal U}[1, \ldots, n]$

\ \ \ \ \ \ \  {\bf Update $s$ value:} $s_{j_i}^{i+1}\leftarrow(1-\eta_{i})s_{j_i}^{i}+\eta_{i}(x_{j_{i}}^{T}\tbeta^{i})$,  and $s_{j}^{i+1} \gets s_{j}^{i}$ for $j \ne j_i$ \medskip

\ \ \ \ \ \ \  {\bf Update substitute gradient:}  $d^{i+1}= \frac{1}{n}X^T\nabla L(s^{i+1}) =  d^i+\frac{1}{n}\left(\dot{l}_{j_{i}}(s^{i+1}_{j_i})-\dot{l}_{j_{i}}(s^i_{j_{i}})\right)x_{j_{i}}$\\ \medskip

\ \ \ \ \ \ \  {\bf Update primal variable:} $\bbeta^{i} \leftarrow (1-\alpha_i) \bbeta^{i-1} + \alpha_i \tbeta^i$.\medskip

\ \ \ \ \ \ \  {\bf (Optional Accounting:)} $w^{i+1} \gets \nabla L(s^{i+1})$ \medskip
\end{algorithmic}
\end{algorithm}

\begin{equation}\label{eq:dual}
\mathrm{(D):} \ \ \ \ \ \ \ \max_{w} D(w):=-R^{*}\left(-\tfrac{1}{n}X^{T}w\right)-\tfrac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w_{j}) \ .
\end{equation}

Notice that we can write:
\begin{equation}\label{eq:altered}R^{*}\left(-\tfrac{1}{n}X^{T}w\right)= - \min_{\beta}\left\{\tfrac{1}{n} w^{T}X\beta+R(\beta)\right\}  \ .
\end{equation}

Also, defining the convex/concave saddle-function $\phi(\cdot,\cdot)$:
\begin{equation}\label{eq:primal-dual}
\phi(\beta,w):=\tfrac{1}{n} w^{T}X\beta-\tfrac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})+R(\beta) \ ,
\end{equation} we can write (P) and (D) in saddlepoint minimax format as:

\begin{equation}\label{eq:minmax} \mathrm{(P):} \ \ \min_{\beta} \max_{w} \phi(\beta,w) \ \ \ \ \  \ \ \mathrm{and} \ \ \ \ \ \ \ \  \mathrm{(D):} \ \ \max_{w}\min_{\beta} \phi(\beta,w) \ .
\end{equation}

\begin{algorithm}
\caption{Randomized Coordinate Mirror Descent applied to the dual problem \eqref{eq:dual}}\label{al:RCMD}
$ \ $
\begin{algorithmic}
\STATE {\bf Initialize.}  Define the prox function $h(w):=\frac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})$.  Initialize with $w^{0}=\arg\min_{w} \tfrac{1}{n}\sum_{i=1}^{n}l_{i}^{*}(w_{i})$ and
step-size sequences $\{\alpha_{i}\} \in (0,1]$ and $\{\eta_{i}\} \in (0,1]$. (Optional: set $\bbeta^{-1}=0$.)\medskip

\STATE  For iterations $i=0,1, \ldots $

\ \ \ \ \ \ \  {\bf Compute Randomized Coordinate of Subgradient of $D(\cdot)$ at $w^i$}\\

\ \ \ \ \ \ \ \ \ \ \ \ Compute $\tbeta^{i} \in \arg\min_{\beta}\left\{\left( \tfrac{1}{n}(w^i)^T X \beta+R(\beta) \right) \right\}$ \\ \medskip

\ \ \ \ \ \ \ \ \ \ \ \    {\bf Choose random index.}  Choose $j_{i} \in {\cal U}[1, \ldots, n]$ \\
%Compute $\bar{\beta}^{i}:=\frac{2}{(4n+k)(k+1)}\sum_{i=0}^{i}(2n+k)\tilde{\beta}^{i}=\frac{(4n+k-1)k}{(4n+k)(k+1)}\bar{\beta}^{k-1}+\frac{2(2n+k)}{(4n+k)(k+1)}\tbeta^{i}$
\ \ \ \ \ \ \ \ \ \ \ \  {\bf Compute subgradient coordinate vector:} $\tilde{g}^i \gets \frac{1}{n}\left(x_{j_{i}}^{T}\tbeta^{i}-\dot{l}_{j_{i}}^{*}(w_{j_{i}}^{i})\right)e_{j_{i}}$ \\ \medskip

\ \ \ \ \ \ \    {\bf Update dual variable:} Compute $w^{i+1}=\arg\min_w \left\{ \left\langle -\eta_{i}\tilde g^i,w-w^{i}\right\rangle +D_{h}(w,w^{i})\right\} $ \\ \medskip

\ \ \ \ \ \ \  {\bf (Optional Accounting:)} $\bbeta^{i} \leftarrow (1-\alpha_i) \bbeta^{i-1} + \alpha_i \tbeta^i$. \medskip

\end{algorithmic}
\end{algorithm}

Notice in Algorithm \ref{al:SFW} and Algorithm \ref{al:RCMD} that $j_i$ is a random variable; and that $s^i$, $d^i$, $w^i$, etc., are random variables that depend on all previous random variable values $j_0, j_1, \ldots, j_{i-1}$, and we denote this string of random variables by 
\begin{equation}\label{eq:xi}
\xi_i=\{j_0, j_1, \ldots, j_{i-1}\} \ .
\end{equation}

\begin{prop}\label{prop:gradient_conjugate}(see \cite{avriel}, \cite{zalinescu}, \cite{kakade2012regularization})
If $f(\cdot)$ is a closed convex function, then ${f}^{**}(\cdot) = f(\cdot)$.  Furthermore:
\begin{enumerate}
\item $\ff$ is $\gamma$-smooth with domain $\RR^p$ with respect to the norm $\|\cdot\|$ if and only if  $f^*(\cdot)$ is $1/\gamma$-strongly convex with respect to the (dual) norm $\|\cdot\|^*$ .
\item If $\ff$ is differentiable and strictly convex, then the following three conditions are equivalent:
\begin{enumerate}
\item $y = \nabla f(x)$
\item $x = \nabla f^*(y)$, and
\item $x^T y = f(x)+f^*(y)$ .
\end{enumerate}
\end{enumerate}
\end{prop}

\begin{lem}\label{tpp} {\bf (Three-Point Property \cite{tseng})} Let $\phi(x)$ be a convex function, and let $\Dh(\cdot, \cdot)$ be the Bregman distance for $\hh$. For a given vector $z$, let
\begin{equation*}
z^+ := \arg\min_{x\in Q} \left\{ \phi(x) + \Dh(x,z) \right\} \ .
\end{equation*}
Then
\begin{equation*}
\phi(x) + \Dh(x,z) \ge \phi(z^+) + \Dh(z^+, z) + \Dh(x,z^+)\ \   for\ all \ x\in Q \ . \qed
\end{equation*}
\end{lem}

