\begin{prop}\label{prop:strong}
$h(\cdot)$ is
$\frac{1}{n\gamma}$-strongly convex with respect to the norm $\|\cdot\|_{2}$.
\end{prop}

{\bf Proof.} Recall that $h(w)=\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w_{j})$. It follows from Assumption \ref{ass:smooth} and Proposition \ref{prop:gradient_conjugate} that $\dls_j(\cdot)$ is $\frac{1}{\gamma}$-strongly convex. Therefore for any $w^1, w^2 \in \dom h(\cdot)$ it holds that:
\begin{equation*}
\begin{array}{lcl}
h(w^1)& = &\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w^1_{j}) \\ \\
& \ge & \frac{1}{n}\sum_{j=1}^{n}\left( l_{j}^{*}(w^2_{j}) + \dls_j(w_j^2)(w_j^1-w_j^2)+\frac{1}{2\gamma}|w^2_j-w^1_j|^2\right) \\ \\
& = & h(w^2) + \langle\nabla h(w^2), w^1-w^2\rangle + \frac{1}{2n\gamma}\|w^2-w^1\|_2^2 \ . \ \qed
\end{array}
\end{equation*}

{\bf Proof.} Recall that $h(w)=\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w_{j})$. It follows from Assumption \ref{ass:smooth} and Proposition \ref{prop:gradient_conjugate} that $\dls_j(\cdot)$ is $\frac{1}{\gamma}$-strongly convex. Therefore for any $w^1, w^2 \in \dom h(\cdot)$ it holds that:
\begin{equation*}
\begin{array}{lcl}
h(w^1)& = &\frac{1}{n}\sum_{j=1}^{n}l_{j}^{*}(w^1_{j}) \\ \\
& \ge & \frac{1}{n}\sum_{j=1}^{n}\left( l_{j}^{*}(w^2_{j}) + \dls_j(w_j^2)(w_j^1-w_j^2)+\frac{1}{2\gamma}|w^2_j-w^1_j|^2\right) \\ \\
& = & h(w^2) + \langle\nabla h(w^2), w^1-w^2\rangle + \frac{1}{2n\gamma}\|w^2-w^1\|_2^2 \ . \ \qed
\end{array}
\end{equation*}

